*{box-sizing:border-box;}
.wrap{height:calc(var(--appsmith-ui-height)*1px);overflow-y:auto;overflow-x:hidden;padding:18px 26px 48px;}
.top{display:flex;align-items:flex-start;gap:58px;margin-bottom:6px;}
.fld label{display:block;font-size:16px;color:var(--appsmith-theme-linkColor, #60a5fa);font-weight:400;margin-bottom:8px;}
.fld select,.dateinput{background:var(--appsmith-theme-backgroundColor, #1E293A);color:var(--appsmith-theme-textColor, #e2e8f0);border:1px solid var(--appsmith-theme-borderColor, #334155);border-radius:6px;padding:9px 12px;font-size:14px;min-width:260px;outline:none;cursor:pointer;height:40px;}
.fld select:focus{border-color:var(--appsmith-theme-linkColor, #60a5fa);}
.dateinput{display:flex;align-items:center;gap:8px;}
.dateinput .ph{color:var(--appsmith-theme-textSecondaryColor, #94a3b8);} .dateinput.has .ph{color:var(--appsmith-theme-textColor, #e2e8f0);}
.dateinput .clr{margin-left:auto;color:var(--appsmith-theme-textSecondaryColor, #94a3b8);font-size:15px;padding:0 2px;}
.dateinput .clr:hover{color:var(--appsmith-theme-textColor, #e2e8f0);}
.pop{position:absolute;top:74px;left:0;z-index:50;background:var(--appsmith-theme-backgroundColor, #1E293A);border:1px solid var(--appsmith-theme-borderColor, #334155);border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.5);padding:14px;width:340px;}
.pop .nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}
.pop .nav b{font-size:15px;color:var(--appsmith-theme-textStrongColor, #ffffff);}
.pop .nav span{cursor:pointer;color:var(--appsmith-theme-textStrongColor, #ffffff);font-size:20px;padding:2px 10px;border-radius:6px;line-height:1;}
.pop .nav span:hover{background:var(--appsmith-theme-surfaceHoverColor, #26344b);}
.pop .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}
.pop .grid b{text-align:center;padding:13px 0;border-radius:8px;font-size:14px;font-weight:600;color:var(--appsmith-theme-textStrongColor, #ffffff);cursor:pointer;}
.pop .grid b:hover{background:var(--appsmith-theme-surfaceHoverColor, #26344b);}
.pop .grid b.on{background:var(--appsmith-theme-actionColor, #2563eb);color:#fff;}
.grp{margin-top:22px;padding-bottom:10px;border-bottom:1px solid var(--appsmith-theme-borderColor, #334155);}
.ghead{display:flex;justify-content:space-between;align-items:baseline;padding:6px 10px 10px;margin-bottom:2px;}
.gmonth{font-size:20px;font-weight:700;color:var(--appsmith-theme-textStrongColor, #ffffff);}
.gtot{font-size:18px;color:var(--appsmith-theme-textStrongColor, #ffffff);}
table{width:100%;border-collapse:collapse;font-size:14px;}
thead th{color:var(--appsmith-theme-textStrongColor, #ffffff);font-weight:600;text-align:left;padding:8px 20px;white-space:nowrap;font-size:15px;}
tbody td{padding:13px 20px;text-align:left;white-space:nowrap;color:var(--appsmith-theme-textStrongColor, #ffffff);font-size:15px;}
tbody tr:nth-child(odd){background:var(--appsmith-theme-surfaceAltColor, #1e293b);}
.link{color:var(--appsmith-theme-linkColor, #60a5fa);cursor:pointer;font-weight:400;text-decoration:underline;}
