    var sStart=(mStart>start)?mStart:start;
    var sEnd=(mEnd<windowEnd)?mEnd:windowEnd;
    var overlap=Math.round((sEnd-sStart)/86400000)+1;
    if(overlap>0) out.push({ mKey:mKey(cur), mLabel:mLabel(cur), start:sStart, end:sEnd, days:overlap, factor:overlap/days });
    cur=new Date(cur.getFullYear(),cur.getMonth()+1,1);
  }
  return out;
}

function calcsOf(bill){ var c=bill.Calcs; if(typeof c==="string"){ try{c=JSON.parse(c);}catch(e){c=[];} } return c||[]; }
function bucketBill(calcs,key,days){
  var t=0;
  calcs.forEach(function(c){
    var n=String(c.name||"");
    if(n==="daily_charges_"+key+"_billblock") t+=Number(c.value||0)*days;
    else if(n==="total_charges_"+key+"_billblock") t+=Number(c.value||0);
  });
  return t;
}

function buildDetail(bill,sl){
  var calcs=calcsOf(bill); var days=Number(bill.Days||0);
  var rows=[];
  rows.push({name:"Start Date", bill:fmtMD(parseD(bill.StartISO)), pro:fmtMD(sl.start)});
  rows.push({name:"End Date", bill:fmtMD(parseD(bill.EndISO)), pro:fmtMD(sl.end)});
  rows.push({name:"Days of Service", bill:String(days), pro:String(sl.days)});
  var tot=Number(bill.Cost||0);
  rows.push({name:"Total Charges", bill:num(tot), pro:num(tot*sl.factor)});
  BUCKETS.forEach(function(b){ var v=bucketBill(calcs,b[1],days); rows.push({name:b[0], bill:cur(v), pro:cur(v*sl.factor)}); });
  return { billId:String(bill["Bill ID"]), vendor:String(bill.Vendor||""), endDate:fmtMD(parseD(bill.EndISO)), rows:rows };
}

function pickerHtml(){
  if(!pickerOpen) return '';
  var cells=MONTHS.map(function(name,i){ var on=(selMonth===name+" "+pickerYear); return '<b class="'+(on?"on":"")+'" data-m="'+i+'">'+M3[i]+'</b>'; }).join('');
  return '<div class="pop" id="pop"><div class="nav"><span data-nav="-1">‹</span><b>'+pickerYear+'</b><span data-nav="1">›</span></div><div class="grid">'+cells+'</div></div>';
}

function render(){
  var m=appsmith.model||{}; var all=m.rows||[];
  EXP=[];
  all.forEach(function(bill){ slices(bill).forEach(function(sl){ EXP.push({bill:bill,sl:sl}); }); });

  var uset={}; all.forEach(function(r){ if(r.Utility) uset[r.Utility]=true; });
  var utils=Object.keys(uset).sort();
  if(selUtil!=="ALL" && utils.indexOf(selUtil)<0) selUtil="ALL";

  var rows=[];
  EXP.forEach(function(x,i){
    if(selUtil!=="ALL" && x.bill.Utility!==selUtil) return;
    if(selMonth && x.sl.mLabel!==selMonth) return;
    rows.push({x:x,i:i});
  });
  rows.sort(function(a,b){ if(a.x.sl.mKey!==b.x.sl.mKey) return b.x.sl.mKey.localeCompare(a.x.sl.mKey); return String(a.x.bill.Utility).localeCompare(String(b.x.bill.Utility)); });

  var order=[], groups={};
  rows.forEach(function(r){ var k=r.x.sl.mLabel; if(!groups[k]){groups[k]=[];order.push(k);} groups[k].push(r); });

  // UBM lists months with no bills between the newest and oldest bill
  if(!selMonth && rows.length){
    var newest=rows[0].x.sl.mKey, oldest=rows[rows.length-1].x.sl.mKey;
    var cy=Number(newest.slice(0,4)), cm=Number(newest.slice(5,7))-1;
    var full=[];
    while(true){
      var d=new Date(cy,cm,1), lbl=mLabel(d);
      full.push(lbl); if(!groups[lbl]) groups[lbl]=[];
      if(mKey(d)<=oldest) break;
      cm--; if(cm<0){cm=11;cy--;}
    }
    order=full;
  }

  var opts='<option value="ALL"'+(selUtil==="ALL"?" selected":"")+'>All Utilities</option>'
    + utils.map(function(u){ return '<option value="'+esc(u)+'"'+(selUtil===u?" selected":"")+'>'+esc(u)+'</option>'; }).join('');
  var dateCls='dateinput'+(selMonth?' has':'');
  var top='<div class="top">'
    +'<div class="fld"><label>Utility Type</label><select id="utilSel">'+opts+'</select></div>'
    +'<div class="fld" style="position:relative"><label>Go to Month</label>'
      +'<div class="'+dateCls+'" id="dateInput">'+CAL+'<span class="ph">'+(selMonth?esc(selMonth):'All months')+'</span>'+(selMonth?'<span class="clr" id="clrMonth">✕</span>':'')+'</div>'
      +pickerHtml()
    +'</div>'
  +'</div>';

  var html=top;
  if(m.isLoading){ html+='<div class="empty">Loading…</div>'; }
  else if(!order.length){ html+='<div class="empty">No bill history'+(selMonth?(' for '+esc(selMonth)):'')+'</div>'; }
  else {
    order.forEach(function(mon){
      var g=groups[mon];
      if(!g.length){ html+='<div class="grp"><div class="ghead"><span class="gmonth">'+esc(mon)+'</span></div><div class="nomonth">No bill history for this time period</div></div>'; return; }
      var monTot=g.reduce(function(s,r){ return s+Number(r.x.bill.Cost||0)*r.x.sl.factor; },0);
      html+='<div class="grp"><div class="ghead"><span class="gmonth">'+esc(mon)+'</span><span class="gtot">Total cost: '+cur(monTot)+'</span></div>';
      html+='<table><thead><tr><th>Bill ID</th><th>Utility</th><th>Cost</th><th>Usage</th><th>Start Date</th><th>End Date</th><th>Days of Service</th><th>Details</th></tr></thead><tbody>';
      var uorder=[], ug={};
      g.forEach(function(r){ var u=r.x.bill.Utility||"—"; if(!ug[u]){ug[u]=[];uorder.push(u);} ug[u].push(r); });
      uorder.forEach(function(u){
        var list=ug[u]; var uCost=0,uUse=0; var uom=(list[0].x.bill.uom||"").toLowerCase();
        list.forEach(function(r){
          var cost=Number(r.x.bill.Cost||0)*r.x.sl.factor;
          var usg=Number(r.x.bill.Usage||0)*r.x.sl.factor;
          uCost+=cost; uUse+=usg;
          html+='<tr>'
            +'<td class="link">'+esc(r.x.bill["Bill ID"])+'</td>'
            +'<td>'+esc(u)+'</td>'
            +'<td>'+cur(cost)+'</td>'
            +'<td>'+num(usg)+(uom?(" "+uom):"")+'</td>'
            +'<td>'+esc(fmtMD(r.x.sl.start))+'</td>'
            +'<td>'+esc(fmtMD(r.x.sl.end))+'</td>'
            +'<td>'+esc(r.x.sl.days)+'</td>'
            +'<td class="link detail" data-i="'+r.i+'">More Details</td>'
            +'</tr>';
        });
        html+='<tr class="totrow"><td></td><td>Total:</td><td>'+cur(uCost)+'</td><td>'+num(uUse)+(uom?(" "+uom):"")+'</td><td></td><td></td><td></td><td></td></tr>';
      });
      html+='</tbody></table></div>';
    });
  }
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+html+'</div>';
  bind();
}

function bind(){
  var sel=document.getElementById("utilSel");
  if(sel) sel.onchange=function(e){ selUtil=e.target.value; render(); };
  var di=document.getElementById("dateInput");
  if(di) di.onclick=function(e){ if(e.target && e.target.id==="clrMonth") return; pickerOpen=!pickerOpen; render(); };
  var clr=document.getElementById("clrMonth");
  if(clr) clr.onclick=function(e){ e.stopPropagation(); selMonth=""; pickerOpen=false; render(); };
  var pop=document.getElementById("pop");
  if(pop){
    var navs=pop.querySelectorAll("[data-nav]");
    for(var i=0;i<navs.length;i++){ (function(s){ s.onclick=function(){ pickerYear+=parseInt(s.getAttribute("data-nav"),10); render(); }; })(navs[i]); }
    var mbs=pop.querySelectorAll("[data-m]");
    for(var j=0;j<mbs.length;j++){ (function(b){ b.onclick=function(){ var k=parseInt(b.getAttribute("data-m"),10); selMonth=MONTHS[k]+" "+pickerYear; pickerOpen=false; render(); }; })(mbs[j]); }
  }
  var dets=document.querySelectorAll(".detail");
  for(var d=0;d<dets.length;d++){ (function(el){ el.onclick=function(){
    var i=parseInt(el.getAttribute("data-i"),10); var x=EXP[i]; if(!x) return;
    appsmith.updateModel({ detail: buildDetail(x.bill,x.sl) });
    appsmith.triggerEvent("onMoreDetails");
  }; })(dets[d]); }
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });
